import{_ as a,o,c as e,a3 as r}from"./chunks/framework.CVt6dz2a.js";const d="/threejs-tutorial-site/assets/EP.34-crs-projection.D-kNRSDR.svg",p=JSON.parse('{"title":"EP.34 一套坐标，一条不能错的链","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.34-crs-projection.md","filePath":"comics/EP.34-crs-projection.md","lastUpdated":1793881879000}'),s={name:"comics/EP.34-crs-projection.md"};function i(c,t,l,u,n,h){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="ep-34-一套坐标-一条不能错的链" tabindex="-1">EP.34 一套坐标，一条不能错的链 <a class="header-anchor" href="#ep-34-一套坐标-一条不能错的链" aria-label="Permalink to &quot;EP.34 一套坐标，一条不能错的链&quot;">​</a></h1><p><img src="'+d+'" alt="EP.34 坐标系、投影与一条不能错的链：像素酱发现模型偏移，码叔拆解三套坐标与投影公式"></p><blockquote><p><strong>对应正文</strong>：<a href="./../guide/34-gis-mapping/basics">34.1 基础入门：坐标系、投影与瓦片</a><strong>延伸阅读</strong>：<a href="./../guide/34-gis-mapping/advanced">34.2 进阶应用：地形、影像与矢量数据上屏</a> · <a href="./../guide/34-gis-mapping/practice">34.3 实战案例：城市级 GIS 场景</a><strong>动手演示</strong>：<a href="./../public/demos/gis/crs-lab.html">crs-lab 坐标系对照台</a> · <a href="./../public/demos/gis/terrain-imagery-lab.html">terrain-imagery-lab 高程与影像地形台</a> · <a href="./../public/demos/gis/gis-scene-lab.html">gis-scene-lab 城市级 GIS 场景台</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>画面</th><th>关键对白</th><th>梗 / 记忆点</th></tr></thead><tbody><tr><td>1</td><td>像素酱站在底图前，虚线框与橙色建筑错开约 200 米</td><td>&quot;楼建好了，底图也对，为什么整体偏了 200 米？&quot;</td><td>两个都&quot;对&quot;，只是坐标系没统一</td></tr><tr><td>2</td><td>码叔推出 WGS84 / GCJ-02 / BD-09 三张卡片</td><td>&quot;同一块地，可能有三套数值；叠错一套，整城平移几百米。&quot;</td><td>偏移量随城市变化，不能用统一常数修补</td></tr><tr><td>3</td><td>投影公式与 ENU 轴向图并排，像素酱记下纪律</td><td>&quot;先投影，再建几何。渲染循环里不转坐标。&quot;</td><td>3857 是切片平面，不是测量平面</td></tr><tr><td>4</td><td>码叔总结三条纪律，标签君补上验收要求</td><td>&quot;纠偏进 ETL，渲染层只认 ENU。&quot; / &quot;交付前用控制点验收。&quot;</td><td>坐标转换全链路只做一次</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-国内地图的三套坐标-先认门牌再谈精度" tabindex="-1">1. 国内地图的三套坐标，先认门牌再谈精度 <a class="header-anchor" href="#_1-国内地图的三套坐标-先认门牌再谈精度" aria-label="Permalink to &quot;1. 国内地图的三套坐标，先认门牌再谈精度&quot;">​</a></h3><p>WGS84 是 GPS 的原始经纬度，GCJ-02 是国内互联网底图常用的加密坐标，BD-09 又是在 GCJ-02 上再偏一次。三套坐标描述同一块地，数值却不同，北京地区的差值通常在数百米量级。工程上不存在&quot;哪套更准&quot;的问题，只有&quot;<strong>数据和底图是不是同一套</strong>&quot;的问题。最稳的做法是：入库时统一转到一个约定的坐标系，把 <code>sourceCrs</code> 与转换参数写进元数据，渲染层不再做二次判断。</p><h3 id="_2-web-mercator-负责-切片-局部-enu-负责-场景" tabindex="-1">2. Web Mercator 负责&quot;切片&quot;，局部 ENU 负责&quot;场景&quot; <a class="header-anchor" href="#_2-web-mercator-负责-切片-局部-enu-负责-场景" aria-label="Permalink to &quot;2. Web Mercator 负责&quot;切片&quot;，局部 ENU 负责&quot;场景&quot;&quot;">​</a></h3><p>Web Mercator（EPSG:3857）用米作单位、经纬线拉直，天生适合切瓦片，所以几乎所有在线底图都用它。但它把高纬度面积拉大，不能当测量平面使用。真正进三维场景时，城市级项目通常再建一个<strong>局部 ENU 切平面</strong>：以城市中心为原点，把经纬度差换算成东向 / 北向的米数，再映射到 Three.js 的 <code>x = east</code>、<code>z = -north</code>。这一步做完，建筑、道路、地形才共享同一套&quot;米&quot;。</p><h3 id="_3-原点与-float32-越远越飘不是玄学" tabindex="-1">3. 原点与 Float32：越远越飘不是玄学 <a class="header-anchor" href="#_3-原点与-float32-越远越飘不是玄学" aria-label="Permalink to &quot;3. 原点与 Float32：越远越飘不是玄学&quot;">​</a></h3><p>&quot;每个城市一个原点&quot;不只是为了数值好看，更是为了精度。<code>float32</code> 的尾数只有 23 位，坐标绝对值越大，可用的最小刻度越粗；再叠加相机近远裁剪面失衡、深度缓冲精度不足，就会出现远处模型边缘闪烁、Z-fighting。解法有优先级：先做浮动原点或按街区 / 瓦片分块，把渲染坐标压到几公里内；再收紧 <code>near/far</code>；最后才考虑对数深度缓冲。</p><h3 id="_4-纠偏属于数据管线-不属于渲染循环" tabindex="-1">4. 纠偏属于数据管线，不属于渲染循环 <a class="header-anchor" href="#_4-纠偏属于数据管线-不属于渲染循环" aria-label="Permalink to &quot;4. 纠偏属于数据管线，不属于渲染循环&quot;">​</a></h3><p>正确的链路是&quot;源数据 → ETL 重投影 / 纠偏 → WGS84 → 城市 ENU → 生成 BufferGeometry → 渲染&quot;。转换要发生在建几何之前，且只做一次。把转换塞进逐帧循环或着色器，既浪费性能，也会让&quot;这份数据到底转没转过&quot;变得无法审计。验收时用控制点抽样比对，把误差写进交付记录。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>误区一：把偏移当成&quot;模型建错了&quot;。</strong> 建筑和底图各偏几百米、方向还一致，八成是坐标系混用；先查 <code>sourceCrs</code>，再查模型。</li><li><strong>误区二：用统一常数修 GCJ-02。</strong> 偏移是地域相关的非线性变换，全国加同一个经纬度差只能让某一块区域&quot;看起来对&quot;。</li><li><strong>误区三：把 Web Mercator 当等距平面。</strong> 在高德 / 百度底图上量出的&quot;米&quot;不是地面真实米，面积统计会系统性偏大。</li><li><strong>误区四：原点只存在配置里，不进数据。</strong> 只改渲染原点、不改数据转换，会让整城平移；原点必须作为元数据与数据一起交付。</li></ul><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>Q1：建筑与底图错位 200 米，第一步该查什么？</b></summary><p>先查坐标系，不查模型。取一条道路交叉口，在底图与建筑数据里各取一个点，打印经纬度与 ENU 坐标：差值固定、方向一致，通常是 WGS84 与 GCJ-02 混用；差值随位置变化，通常是原点或投影不一致；差值是个整齐整数，可能是某处多做了一次平移。</p></details><details><summary><b>Q2：为什么局部 ENU 的 z 轴要写成负的 north？</b></summary><p>Three.js 的默认视角约定是 -Z 朝北、+X 朝东。若直接把 <code>north</code> 赋给 <code>z</code>，整座城市会南北翻转——建筑、道路都还在，方向却反了，截图时很难第一眼发现。所以落场景时统一写 <code>z = -north</code>，并在坐标工具函数里只做一次映射，避免各模块各写一套。</p></details><details><summary><b>Q3：10 万米外的模型抖动，只开对数深度缓冲够吗？</b></summary><p>通常不够。它改善深度分布，但不会修复顶点坐标本身的 float32 精度损失。优先级应是浮动原点 / 分块 → 收紧相机 <code>near/far</code> → 对数深度缓冲；共面物体再加微小 Y 偏移或 <code>polygonOffset</code>。城市级场景还应把&quot;同屏坐标绝对值&quot;作为一条验收指标。</p></details><hr><blockquote><p>下一篇正文见 <a href="./../guide/34-gis-mapping/basics">34.1 基础入门：坐标系、投影与瓦片</a>。漫画仅作概念预热，代码与验收细节以正文为准。</p></blockquote>',22)])])}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
